          ? (F1(-1, ++V2, V3),
             ((V5 = (int)(V4 = (int)(V2 + 1) /
                               (1 - (int)V3 * 2 - (int)V3 * (int)V3),
                          V4 * V4 >= 1 && ((2 % 3) / 4 - 2 + (V4 / 2)) < 1),
               printf("c: %d %d %d %f %d\n", V1, V2, V3, V4, V5), V5)["ab"]))
